    for (const [dr, dc] of directions) {
      const nr = r + dr; const nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] === 0 && !visited.has(nr + ',' + nc)) { visited.add(nr + ',' + nc); queue.push([nr, nc, distance + 1]); }
    }
  }
  return -1;
